        CaptionLine(
          start: Duration(milliseconds: 16802),
          end: Duration(milliseconds: 22202),
          text:
              '“Maybe Uncle Farhan took it years ago and forgot,” Imaan said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 22908),
          end: Duration(milliseconds: 24202),
          text: 'Akhlaaq looked at her.',
        ),
        CaptionLine(
