        ),
        CaptionLine(
          start: Duration(milliseconds: 47554),
          end: Duration(milliseconds: 51466),
          text: 'At school, the missing page was still on her mind.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 51466),
          end: Duration(milliseconds: 54574),
          text: 'She told Ms Sana what they had found.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 54574),
          end: Duration(milliseconds: 56737),
          text: '“What do you know for certain?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 56737),
          end: Duration(milliseconds: 57866),
          text: 'Ms Sana asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 57866),
          end: Duration(milliseconds: 60746),
          text: '“A page is missing,” Imaan said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 60746),
          end: Duration(milliseconds: 61929),
          text: '“What else?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 62520),
          end: Duration(milliseconds: 64146),
          text: 'Ms Sana asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 64146),
          end: Duration(milliseconds: 69186),
          text:
              '“The page probably contained an important calculation,” Imaan said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 69186),
          end: Duration(milliseconds: 72039),
          text: '“And do you know who removed it?”',
        ),
        CaptionLine(
