        ),
        CaptionLine(
          start: Duration(milliseconds: 154746),
          end: Duration(milliseconds: 158506),
          text: 'Farhan looked at the notebook.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 158506),
          end: Duration(milliseconds: 169106),
          text:
