        ),
        CaptionLine(
          start: Duration(milliseconds: 169106),
          end: Duration(milliseconds: 172093),
          text: '“Could it have been you?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 172757),
          end: Duration(milliseconds: 173586),
          text: 'Imaan asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 173586),
          end: Duration(milliseconds: 178082),
