        CaptionLine(
          start: Duration(milliseconds: 229242),
          end: Duration(milliseconds: 233842),
          text: 'Farhan turned to the old photograph of the workshop.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 233842),
          end: Duration(milliseconds: 240714),
          text:
